using ghidra.trace.model.target.schema;

public class RmiRemoteMethodParameter {

	private string name;
	private TraceObjectSchema schema;
	private bool required;
	private object defaultValue;
	private string display;
	private string description;

	public RmiRemoteMethodParameter(string name, TraceObjectSchema schema, bool required,
			object defaultValue, string display, string description) {
		this.name = name;
		this.schema = schema;
		this.required = required;
		this.defaultValue = defaultValue;
		this.display = display;
		this.description = description;
	}

	public string getName() {
		return name;
	}

	public string getDescription() {
		return description;
	}

	public string getDisplay() {
		return display;
	}

	public ValueType getType() {
		string schemaName = schema.getName().toString();
//		if (schemaName.equals("ANY")) {
//			return ValueType.newBuilder().setName("OBJECT").build();
//		}
		return ValueType.newBuilder().setName(schemaName).build();
	}

	public object getDefaultValue() {
		return defaultValue;
	}

	public bool isRequired() {
		return required;
	}
}
